import { thumbHashToDataURL } from "thumbhash";
import { countdown, nextTick, seasonAt, type Season, type SeasonState } from "./season.ts";

/** Generated by scripts/build.ts from src/backgrounds.ts. */
export interface Photo {
  /** URL prefix; each width is served at `${src}-${width}.{avif,jpg}`. */
  src: string;
  widths: number[];
  ratio: number;
  /** Base64 ThumbHash, decoded into the placeholder shown before the photo loads. */
  hash: string;
}

declare const PHOTOS: Record<Season, Photo[]>;
declare const ANALYTICS_HOST: string;
declare global {
  /** Called by an inline script right after the markup, so the timer is filled before it can paint. */
  var mountSeason: () => void;
}

// Top-level code below runs on load, so helpers must be hoisted function declarations.
const root = document.documentElement;

let state: SeasonState;
let photo: Photo;
let timer: ReturnType<typeof setTimeout>;

// Runs in <head>, before first paint: everything here is visible on the first frame.
enterSeason(seasonAt(Date.now()));
preload(photo!);

// Not DOMContentLoaded: on slow connections the browser paints the streamed HTML well before that.
globalThis.mountSeason = () => {
  showPhoto();
  tick();
  root.dataset.ready = "";
  document.addEventListener("visibilitychange", () => document.hidden || tick());
  addEventListener("pageshow", (e) => e.persisted && tick());
  addEventListener("load", count, { once: true });
};

function enterSeason(next: SeasonState) {
  state = next;
  const choices = PHOTOS[state.season];
  photo = choices[Math.floor(Math.random() * choices.length)]!;
  root.dataset.season = state.season;
  root.style.setProperty("--placeholder", `url(${thumbHashToDataURL(fromBase64(photo.hash))})`);
  document.title = `It's ${state.season} in Horizon`;
}

function tick() {
  clearTimeout(timer);
  const now = Date.now();
  if (now >= state.endsAt) {
    enterSeason(seasonAt(now));
    showPhoto();
    $("announce").textContent = `It's now ${state.season} in Horizon.`;
  }
  const remaining = state.endsAt - now;
  renderCountdown(remaining);
  timer = setTimeout(tick, nextTick(remaining));
}

function renderCountdown(remaining: number) {
  const parts = countdown(remaining);
  $("season-name").textContent = state.season;
  $("next").textContent = state.next;
  const time = $<HTMLTimeElement>("time");
  time.dateTime = new Date(state.endsAt).toISOString();
  time.title = new Date(state.endsAt).toLocaleString(undefined, { dateStyle: "full", timeStyle: "short" });
  $("time-visual").replaceChildren(
    ...parts.flatMap(({ value, unit }) => [span("value", value), span(unit.length > 1 ? "unit word" : "unit", unit)]),
  );
  $("time-spoken").textContent = parts.map((p) => p.spoken).join(", ");
}

function showPhoto() {
  const img = $<HTMLImageElement>("photo");
  const source = img.previousElementSibling as HTMLSourceElement;
  img.removeAttribute("data-loaded");
  img.onload = () => (img.dataset.loaded = "");
  source.srcset = srcset(photo, "avif");
  source.sizes = img.sizes = sizes(photo);
  img.srcset = srcset(photo, "jpg");
  img.src = `${photo.src}-${photo.widths.at(-1)}.jpg`;
  // Cached images may already be decoded: show them without a fade.
  if (img.complete && img.naturalWidth) img.dataset.loaded = "";
}

function preload(p: Photo) {
  const link = document.createElement("link");
  link.rel = "preload";
  link.as = "image";
  link.type = "image/avif";
  link.fetchPriority = "high";
  link.imageSrcset = srcset(p, "avif");
  link.imageSizes = sizes(p);
  document.head.append(link);
}

function srcset(p: Photo, ext: string) {
  return p.widths.map((w) => `${p.src}-${w}.${ext} ${w}w`).join();
}

// Portrait/square layouts blur the photo, so a small one is plenty. Otherwise the photo
// covers the viewport: full width when the viewport is wider than the photo, else full height.
function sizes(p: Photo) {
  return `(max-aspect-ratio: 1/1) 40vw, (min-aspect-ratio: ${Math.round(p.ratio * 1000)}/1000) 100vw, ${Math.ceil(p.ratio * 100)}vh`;
}

function $<T extends HTMLElement>(id: string) {
  return document.getElementById(id) as T;
}

function span(className: string, text: string) {
  const el = document.createElement("span");
  el.className = className;
  el.textContent = text;
  return el;
}

function fromBase64(b64: string) {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

function count() {
  if (location.hostname !== ANALYTICS_HOST) return;
  const params = new URLSearchParams({
    p: location.hostname + location.pathname,
    t: document.title,
    r: document.referrer,
    s: `${screen.width},${screen.height},${devicePixelRatio}`,
  });
  new Image().src = `https://tuckerchapin.goatcounter.com/count?${params}`;
}
